//! The network mount service `mountd` (docs/smb-plan.md §3.4).
//!
//! The `os.lazy.mount.v1` stubs and the blocking [`Client`] are generated by
//! `midlc` from `idl/mount.midl`; this module names them for native programs.
//! Its other clients are the Network Drives app (`xui-app`) and scripts (`sys::mount` in `rhai`).



use super::client::Native;

/// The generated `os.lazy.mount.v1` stubs.
pub use messenger_generated::os_lazy_mount_v1 as wire;

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `mountd` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A blocking client of `mountd`: `Client::try_connect(Native)`.
pub type Client = wire::Client<Native>;
